}

/// Session ids come from the harness's UUIDv7: the old local LCG here
/// collapsed under dart2js (int is a double; the multiply overflowed 2^53
/// and zeroed the low bits), so two sessions minted close together could
/// share an id and one's archive file overwrote the other — sessions
/// "disappeared" from the picker. uuidv7 is time-ordered and secure-random.
String _uuid() => uuidv7();

/// Compaction progress sink that reports nothing (headless SW).
final class _SilentHooks implements AutoCompactorHooks {
  @override
  void onPass(AutoCompactorPass pass) {}
  @override
  void onRetry(int attempt, int maxAttempts, Duration backoff, Object error) {}
  @override
  void onDone(int passes, int tokens) {}
  @override
  void onBothRolesFailed(Object lastError) {}
  @override
  void onDelta(String delta) {}
  @override
  void onAttemptStart(String label, int attempt, Duration budget) {}
}

/// The ext_request backend over the SW's chrome binding + fetch client.
final class _ExtOpsBackend implements ExtOpsBackend {
  _ExtOpsBackend(this._host);

  final AgentHost _host;

  @override
  Future<List<ExtCookie>> cookiesGetAll({String? url, String? domain}) async {
    final chrome = _host._chromeApi;
    if (chrome == null) throw 'no chrome binding (v1-only build)';
    final cookies = await chrome.cookies.getAll(url: url, domain: domain);
    return [
      for (final c in cookies)
        ExtCookie(name: c.name, value: c.value, domain: c.domain),
    ];
  }

  @override
  Future<ExtHttpResponse> fetchString(
    String url, {
    String method = 'GET',
    Map<String, String> headers = const {},
    String? body,
  }) => _host._extFetch(url, method: method, headers: headers, body: body);

  @override
  Future<void> tabsCreate(String url) async {
    final chrome = _host._chromeApi;
    if (chrome == null) throw 'no chrome binding (v1-only build)';
    await chrome.tabs.create(url: url);
  }

  @override
  Future<String> stageUpload(String name, Uint8List bytes) =>
      // The same core routine the app's AgentService.stageAttachment runs
      // (issue #313): identical sanitize/dedupe/uploads/ semantics —
      // through the host's StageGate so concurrent ops cannot interleave
      // (review E3).
      _host._stageGate.run(
        () => uploads.stageUpload(_host._env, name: name, bytes: bytes),
      );

  @override
  Future<void> discardUpload(String path) async {
    if (!path.startsWith('${uploads.uploadsDirName}/')) return;
    try {
      await _host._env.remove(path);
    } on Object {
      // Best effort: a leftover file in uploads/ is harmless.
    }
  }

  @override
  Future<List<String>> missingUploads(List<String> paths) async {
    final missing = <String>[];
    for (final path in paths) {
      if ((await _host._env.exists(path)).valueOrNull != true) {
        missing.add(path);
      }
    }
    return missing;
  }
}

// Provider stream construction + the synced-provider registry for the
// extension agent: an OpenAI-like streaming function over the core
// `streamOpenAICompletions` adapter (pure and web-safe), resolution for
// the deterministic `fake:` provider (fake_provider.dart — pure Dart,
// VM-testable; re-exported here so the agent host keeps a single import),
// and the `faProviders` registry that the bridge `providersSync` frame
// fills (issue #34 item 3, §S6) with `.fahx` imports and panel edits.
//
// Everything here is pure Dart: the JS glue lives in bridge_relay.dart
// (faSw.bridge) and agent_main.dart. The core sse_decoder is reused
// INSIDE the core adapter — nothing here parses SSE by hand; the only
// web-specific piece is the fetch-backed http.Client (see fetch_client.dart)
// installed once at boot.
import 'dart:async';
import 'dart:convert';

import 'package:flutter_agent_harness/src/agent/agent_loop.dart'
    show StreamFunction;
import 'package:flutter_agent_harness/src/cancel_token.dart';
import 'package:flutter_agent_harness/src/context.dart';
