  /// 1-based pass number.
  final int pass;

  /// Estimated tokens before the pass.
  final int tokensBefore;

  /// Estimated tokens after the pass.
  final int tokensAfter;

  /// Which summarizer was used: `'smol'`, `'main'`, or `null` when the
