) {
  String field(String name) {
    final v = incoming[name];
    if (v is String && v.trim().isNotEmpty) return v;
    final s = stored?[name];
    if (s is String) return s;
    return '';
  }

  return {
    'baseUrl': field('baseUrl'),
    'apiKey': [REDACTED:Sensitive-Value]'apiKey'),
    'model': field('model'),
  };
