  // ^-anchored: the host prepends a "[context] active tab: …" line to
  // turns (issue #34) — an anchored match never fires (same trap the dm
  // directive hit in issue #41).
  final inject = RegExp(
    r'inject_js (\d+) (\S+) (.+)',
    dotAll: true,
